{
  "name": "@sonar-ai/risk-engine",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "dependencies": {
    "@sonar-ai/core": "workspace:*"
  },
  "devDependencies": {
    "@types/node": "^20.19.43",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  }
}

import type { PortfolioSnapshot, ProposedAction } from "@sonar-ai/core";

/**
 * Risk math runs in weight-space (fractions of NAV), independent of prices.
 * A `ProposedAction.targetWeight` is the resulting weight for that instrument
 * after the action, so the proposed portfolio is the current position weights
 * overridden by any action targets.
 */
export type WeightMap = Map<string, number>;

/** Current weights per instrument from a portfolio snapshot. */
export function currentWeights(portfolio: PortfolioSnapshot): WeightMap {
  const map: WeightMap = new Map();
  for (const p of portfolio.positions) map.set(p.instrumentId, p.weight);
  return map;
}

/**
 * Proposed weights = current weights with each action's `targetWeight` applied
 * as the new absolute weight for its instrument. `overrides` lets the engine
 * substitute post-resize weights for specific actions.
 */
export function proposedWeights(
  portfolio: PortfolioSnapshot,
  actions: readonly ProposedAction[],
  overrides?: ReadonlyMap<string, number>,
): WeightMap {
  const map = currentWeights(portfolio);
  for (const a of actions) {
    const w = overrides?.get(a.id) ?? a.targetWeight;
    map.set(a.instrumentId, w);
  }
  return map;
}

/** Total invested weight (sum of all position weights). */
export function investedWeight(weights: WeightMap): number {
  let sum = 0;
  for (const w of weights.values()) sum += w;
  return sum;
}

import type { Instrument, RiskMetrics } from "@sonar-ai/core";
import type { WeightMap } from "./weights";

/**
 * Optional per-instrument risk statistics. Absent an entry, an instrument is
 * treated as beta 1.0, volatility 0. These feed simplified portfolio metrics.
 */
export type InstrumentStats = Record<
  string,
  { volatility: number; beta: number }
>;

function sectorOf(instrumentId: string, instruments: readonly Instrument[]): string {
  return instruments.find((i) => i.id === instrumentId)?.sector ?? "Unknown";
}

/** Exposure by sector name, each a fraction of NAV. */
export function sectorExposure(
  weights: WeightMap,
  instruments: readonly Instrument[],
): Record<string, number> {
  const out: Record<string, number> = {};
  for (const [instrumentId, w] of weights) {
    if (w === 0) continue;
    const sector = sectorOf(instrumentId, instruments);
    out[sector] = (out[sector] ?? 0) + w;
  }
  return out;
}

/** Concentration = the largest single-position weight (0 for an empty book). */
export function concentration(weights: WeightMap): number {
  let max = 0;
  for (const w of weights.values()) max = Math.max(max, w);
  return max;
}

/**
 * Simplified portfolio beta: the weight-weighted average of instrument betas.
 * MVP metric — it is not a covariance model, and it is labeled as such in docs.
 */
export function portfolioBeta(weights: WeightMap, stats: InstrumentStats): number {
  let beta = 0;
  for (const [id, w] of weights) beta += w * (stats[id]?.beta ?? 1);
  return beta;
}

/**
 * Simplified portfolio volatility: the weight-weighted average of instrument
 * volatilities. MVP metric, not a covariance-based figure.
 */
export function portfolioVolatility(
  weights: WeightMap,
  stats: InstrumentStats,
): number {
  let vol = 0;
  for (const [id, w] of weights) vol += w * (stats[id]?.volatility ?? 0);
  return vol;
}

/** Compute the full deterministic metric set for a proposed weight map. */
export function computeMetrics(
  weights: WeightMap,
  instruments: readonly Instrument[],
  stats: InstrumentStats = {},
): RiskMetrics {
  return {
    volatility: portfolioVolatility(weights, stats),
    beta: portfolioBeta(weights, stats),
    concentration: concentration(weights),
    sectorExposure: sectorExposure(weights, instruments),
  };
}

import type {
  Currency,
  PortfolioComparison,
  PortfolioSnapshot,
} from "@sonar-ai/core";
import { currentWeights, investedWeight, type WeightMap } from "./weights";

/** Round to cents to keep money math free of float dust. */
function money(amount: number, currency: Currency) {
  return { amount: Math.round(amount * 100) / 100, currency };
}

/**
 * Deterministic current-versus-proposed comparison. For the MVP baseline this
 * compares the all-cash portfolio against the proposed allocation and the cash
 * it retains.
 */
export function comparePortfolios(
  current: PortfolioSnapshot,
  proposed: WeightMap,
): PortfolioComparison {
  const nav = current.nav.amount;
  const currency = current.baseCurrency;
  const invested = investedWeight(proposed);

  const cur = currentWeights(current);
  const instrumentIds = new Set<string>([...cur.keys(), ...proposed.keys()]);

  const deltas = [...instrumentIds]
    .map((instrumentId) => ({
      instrumentId,
      currentWeight: cur.get(instrumentId) ?? 0,
      proposedWeight: proposed.get(instrumentId) ?? 0,
    }))
    .filter((d) => d.currentWeight !== 0 || d.proposedWeight !== 0)
    .sort((a, b) => a.instrumentId.localeCompare(b.instrumentId));

  return {
    currentNav: money(nav, currency),
    proposedInvested: money(invested * nav, currency),
    proposedCash: money((1 - invested) * nav, currency),
    deltas,
  };
}

import type { Currency, StressResult } from "@sonar-ai/core";
import { portfolioBeta, type InstrumentStats } from "./metrics";
import type { WeightMap } from "./weights";

/**
 * A deterministic stress scenario. Either supply per-instrument return shocks
 * (fractions, e.g. -0.2 for -20%) or a broad `marketShock` applied through
 * portfolio beta. Per-instrument shocks take precedence where present.
 */
export interface StressScenario {
  name: string;
  shockByInstrument?: Record<string, number>;
  marketShock?: number;
}

/** Apply one stress scenario to a proposed weight map. */
export function runStressTest(
  weights: WeightMap,
  navAmount: number,
  currency: Currency,
  scenario: StressScenario,
  stats: InstrumentStats = {},
): StressResult {
  let pct = 0;
  const perInstrument = scenario.shockByInstrument ?? {};

  for (const [id, w] of weights) {
    if (id in perInstrument) {
      pct += w * (perInstrument[id] ?? 0);
    } else if (scenario.marketShock !== undefined) {
      pct += w * scenario.marketShock * (stats[id]?.beta ?? 1);
    }
  }

  const navImpact = pct * navAmount;
  return {
    scenario: scenario.name,
    navImpact: { amount: Math.round(navImpact * 100) / 100, currency },
    navImpactPct: pct,
  };
}

import type { Mandate, ProposedAction } from "@sonar-ai/core";

const EPS = 1e-9;

export interface ActionValidation {
  ok: boolean;
  detail: string;
  numbers: Record<string, number>;
}

/**
 * DATA_INVALID guard for a single action. A proposal is only as trustworthy as
 * its inputs: the currency must match the mandate, the target weight must be a
 * fraction in [0, 1], and the stated amount must agree with `targetWeight × NAV`
 * within 1% of NAV. Anything else is rejected before it can size a trade.
 */
export function validateAction(
  action: ProposedAction,
  mandate: Mandate,
  nav: number,
): ActionValidation {
  const numbers: Record<string, number> = {
    targetWeight: action.targetWeight,
    amount: action.amount.amount,
  };

  if (action.amount.currency !== mandate.baseCurrency) {
    return {
      ok: false,
      detail: `Action currency ${action.amount.currency} does not match mandate base ${mandate.baseCurrency}.`,
      numbers,
    };
  }
  if (
    !Number.isFinite(action.targetWeight) ||
    action.targetWeight < -EPS ||
    action.targetWeight > 1 + EPS
  ) {
    return {
      ok: false,
      detail: `Target weight ${action.targetWeight} is outside [0, 1].`,
      numbers,
    };
  }

  const expected = action.targetWeight * nav;
  const tolerance = Math.max(1, 0.01 * nav);
  numbers.expectedAmount = expected;
  if (Math.abs(action.amount.amount - expected) > tolerance) {
    return {
      ok: false,
      detail: `Amount ${action.amount.amount} disagrees with targetWeight×NAV (${expected}).`,
      numbers,
    };
  }

  return { ok: true, detail: "Action inputs are consistent.", numbers };
}

import type { Mandate, ProposedAction } from "@sonar-ai/core";

const EPS = 1e-9;

export interface PositionLimitOutcome {
  /** Effective weight after applying the limit. */
  weight: number;
  /** Effective notional after applying the limit. */
  amount: number;
  resized: boolean;
  numbers: Record<string, number>;
}

/**
 * The single-position limit is enforced by RESIZING, not rejecting: an action
 * over `maxGrossExposurePerPosition` is trimmed to the limit so the demo shows
 * the mandate constraining a trade rather than dead-ending the run.
 */
export function applyPositionLimit(
  action: ProposedAction,
  mandate: Mandate,
  nav: number,
): PositionLimitOutcome {
  const limit = mandate.limits.maxGrossExposurePerPosition;

  if (action.targetWeight > limit + EPS) {
    const amount = Math.round(limit * nav * 100) / 100;
    return {
      weight: limit,
      amount,
      resized: true,
      numbers: {
        proposedWeight: action.targetWeight,
        positionLimit: limit,
        resizedWeight: limit,
      },
    };
  }

  return {
    weight: action.targetWeight,
    amount: action.amount.amount,
    resized: false,
    numbers: { positionWeight: action.targetWeight, positionLimit: limit },
  };
}

import type { Mandate } from "@sonar-ai/core";

const EPS = 1e-9;

export interface SectorBreach {
  sector: string;
  exposure: number;
  limit: number;
}

/**
 * Sector exposures over `maxSectorExposure`. Unlike the position limit, a sector
 * breach is a HARD BLOCK — the Risk Officer stops the proposal and the Portfolio
 * Manager must revise; the engine does not silently trim it.
 */
export function checkSectorLimits(
  sectorExposure: Record<string, number>,
  mandate: Mandate,
): SectorBreach[] {
  const limit = mandate.limits.maxSectorExposure;
  return Object.entries(sectorExposure)
    .filter(([, exposure]) => exposure > limit + EPS)
    .map(([sector, exposure]) => ({ sector, exposure, limit }))
    .sort((a, b) => a.sector.localeCompare(b.sector));
}

export interface CashFloorOutcome {
  ok: boolean;
  cashRatio: number;
  minCashRatio: number;
}

/** The minimum-cash floor. A breach is a hard block. */
export function checkCashFloor(
  investedWeight: number,
  mandate: Mandate,
): CashFloorOutcome {
  const minCashRatio = mandate.limits.minCashRatio;
  const cashRatio = 1 - investedWeight;
  return { ok: cashRatio >= minCashRatio - EPS, cashRatio, minCashRatio };
}

export interface TurnoverOutcome {
  ok: boolean;
  turnover: number;
  maxTurnover: number;
}

/**
 * Turnover = total effective notional moved by this event, as a fraction of
 * NAV. A breach is a hard block.
 */
export function checkTurnover(
  effectiveNotional: number,
  nav: number,
  mandate: Mandate,
): TurnoverOutcome {
  const maxTurnover = mandate.limits.maxTurnoverPerEvent;
  const turnover = nav > 0 ? effectiveNotional / nav : 0;
  return { ok: turnover <= maxTurnover + EPS, turnover, maxTurnover };
}

