import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Workspace packages are published as TypeScript source (exports -> ./src),
  // so Next must transpile them rather than expecting pre-built JS.
  transpilePackages: ["@sonar-ai/core", "@sonar-ai/risk-engine"],
};

export default nextConfig;

import { z } from "zod";

/**
 * Validated, server-only environment. NEVER import this from a client
 * component — every value here is a secret or a server switch and must not
 * reach the browser. See `.env.example` for the full list and rules.
 */

const EnvSchema = z.object({
  // Runtime
  SONAR_OFFLINE: z
    .enum(["true", "false"])
    .default("true")
    .transform((v) => v === "true"),

  // OpenAI (all agents)
  OPENAI_API_KEY: z.string().optional(),
  OPENAI_BASE_URL: z.url().optional(),
  OPENAI_ORG_ID: z.string().optional(),
  OPENAI_PROJECT_ID: z.string().optional(),
  SONAR_AGENT_MODEL: z.string().default("gpt-5"),
  SONAR_AGENT_MAX_TOKENS: z.coerce.number().int().positive().default(4096),
  SONAR_AGENT_MAX_RETRIES: z.coerce.number().int().min(0).default(1),

  // Cala (server-only)
  CALA_API_KEY: z.string().optional(),
  CALA_MCP_ENDPOINT: z.string().default("https://api.cala.ai/mcp/"),
  CALA_TIMEOUT_MS: z.coerce.number().int().positive().default(15000),

  // eToro (read-only, unverified)
  ETORO_API_KEY: z.string().optional(),
  ETORO_API_BASE: z.string().optional(),
  ETORO_TIMEOUT_MS: z.coerce.number().int().positive().default(15000),
});

export type ServerEnv = z.infer<typeof EnvSchema>;

let cached: ServerEnv | undefined;

/**
 * Parse and cache the server environment. Empty-string variables are treated as
 * unset so defaults apply. Throws a readable error if a present value is
 * malformed (e.g. a non-URL `OPENAI_BASE_URL`).
 */
export function getServerEnv(): ServerEnv {
  if (cached) return cached;
  const raw = Object.fromEntries(
    Object.entries(process.env).filter(([, v]) => v !== undefined && v !== ""),
  );
  const parsed = EnvSchema.safeParse(raw);
  if (!parsed.success) {
    throw new Error(
      `Invalid server environment:\n${JSON.stringify(parsed.error.flatten().fieldErrors, null, 2)}`,
    );
  }
  cached = parsed.data;
  return cached;
}

/** True when the app must run entirely from fixtures with no external calls. */
export function isOffline(): boolean {
  return getServerEnv().SONAR_OFFLINE;
}

import type { AgentStage } from "@sonar-ai/core";
import type { ZodType } from "zod";

/**
 * The seam between deterministic stubs and real OpenAI calls.
 *
 * Agents are DATA, runners are BEHAVIOR. Each agent is an {@link AgentDef}:
 * a stage id, instructions, an output schema, and a function that turns its
 * isolated context pack into a model input. A {@link AgentRunner} executes a
 * def. `StubAgentRunner` (Phase 3) returns canned fixture outputs;
 * `OpenAIAgentRunner` (Phase 5) calls the model — swapping one for the other is
 * the only change needed to go from an offline demo to live agents.
 */

/** One committee agent, defined by what it must produce — never an SDK call. */
export interface AgentDef<TContext, TOutput> {
  stage: AgentStage;
  /** System / instruction prompt for this agent. */
  instructions: string;
  /**
   * Zod schema the output must satisfy. Also the source of the OpenAI
   * structured-output JSON schema, so the model can never return a shape the
   * contract does not accept.
   */
  outputSchema: ZodType<TOutput>;
  /** Build the model input from the isolated context pack. */
  buildInput(context: TContext): string;
}

export interface AgentUsage {
  inputTokens: number;
  outputTokens: number;
}

export interface AgentRunResult<TOutput> {
  output: TOutput;
  usage?: AgentUsage;
}

/**
 * Executes an {@link AgentDef}. Implementations MUST validate the produced
 * output against `def.outputSchema` before returning, and MUST NOT leak
 * prompts, credentials, or hidden reasoning to their caller — only the typed
 * output crosses this boundary.
 */
export interface AgentRunner {
  run<TContext, TOutput>(
    def: AgentDef<TContext, TOutput>,
    context: TContext,
  ): Promise<AgentRunResult<TOutput>>;
}

import type { AgentStage } from "@sonar-ai/core";
import type { AgentDef, AgentRunner, AgentRunResult } from "./types";

/**
 * Deterministic runner for Phase 3. Returns a canned output per stage (drawn
 * from a fixture) instead of calling a model, so the whole orchestrator —
 * phase transitions, the evidence gate, the risk hard-block, the approval gate,
 * the receipt — can be proven end-to-end with zero LLM flakiness and zero
 * network. Swapped for `OpenAIAgentRunner` in Phase 5 without touching the
 * orchestrator.
 *
 * Every returned output is still validated against `def.outputSchema`, so the
 * stub cannot silently drift from the contract.
 */
export class StubAgentRunner implements AgentRunner {
  constructor(private readonly outputs: Partial<Record<AgentStage, unknown>>) {}

  async run<TContext, TOutput>(
    def: AgentDef<TContext, TOutput>,
    _context: TContext,
  ): Promise<AgentRunResult<TOutput>> {
    const canned = this.outputs[def.stage];
    if (canned === undefined) {
      throw new Error(`StubAgentRunner: no canned output for stage "${def.stage}".`);
    }
    const parsed = def.outputSchema.safeParse(canned);
    if (!parsed.success) {
      throw new Error(
        `StubAgentRunner: canned output for "${def.stage}" fails its schema:\n${JSON.stringify(
          parsed.error.issues,
          null,
          2,
        )}`,
      );
    }
    return { output: parsed.data };
  }
}

import type { ZodType } from "zod";

/**
 * The CLOSED set of capabilities an agent may reach. Nothing outside this list
 * is callable, no tool submits an order or touches a brokerage account, and no
 * agent calls another directly — the orchestrator is the only sequencer.
 */
export const TOOL_NAMES = [
  "get_portfolio_snapshot",
  "get_price_history",
  "get_company_fundamentals",
  "search_company_information", // -> Cala relationship tracing / fixture
  "calculate_portfolio_metrics", // -> risk-engine
  "calculate_asset_exposure", // -> risk-engine
  "run_stress_test", // -> risk-engine
  "compare_portfolio_scenarios", // -> risk-engine
  "get_existing_thesis",
  "save_recommendation", // writes internal state only
] as const;

export type ToolName = (typeof TOOL_NAMES)[number];

/**
 * Services the orchestrator injects into every tool call. Adapters resolve to
 * Cala/eToro or a fixture depending on `offline`.
 */
export interface ToolContext {
  offline: boolean;
}

/** One typed, schema-validated capability. */
export interface Tool<TInput, TOutput> {
  name: ToolName;
  description: string;
  inputSchema: ZodType<TInput>;
  outputSchema: ZodType<TOutput>;
  execute(input: TInput, ctx: ToolContext): Promise<TOutput>;
}

export type AnyTool = Tool<unknown, unknown>;

/** The registry the orchestrator hands to agents — keyed by the closed name set. */
export type ToolRegistry = Partial<Record<ToolName, AnyTool>>;

