import { describe, expect, it } from "vitest";
import { runStressTest } from "../stress";
import type { WeightMap } from "../weights";

const WEIGHTS: WeightMap = new Map([
  ["inst_nvidia", 0.3],
  ["inst_siemens", 0.2],
]);

describe("runStressTest", () => {
  it("applies per-instrument shocks weighted by position size", () => {
    const result = runStressTest(WEIGHTS, 1000, "EUR", {
      name: "NVDA -20%",
      shockByInstrument: { inst_nvidia: -0.2 },
    });
    // 0.30 × -0.20 = -0.06 ; -0.06 × 1000 = -60
    expect(result.navImpactPct).toBeCloseTo(-0.06, 10);
    expect(result.navImpact.amount).toBeCloseTo(-60, 10);
    expect(result.scenario).toBe("NVDA -20%");
  });

  it("applies a broad market shock through instrument beta", () => {
    const result = runStressTest(
      WEIGHTS,
      1000,
      "EUR",
      { name: "Market -10%", marketShock: -0.1 },
      {
        inst_nvidia: { volatility: 0, beta: 1.5 },
        inst_siemens: { volatility: 0, beta: 0.8 },
      },
    );
    // 0.30×-0.1×1.5 + 0.20×-0.1×0.8 = -0.045 - 0.016 = -0.061
    expect(result.navImpactPct).toBeCloseTo(-0.061, 10);
    expect(result.navImpact.amount).toBeCloseTo(-61, 10);
  });

  it("prefers a per-instrument shock over the market shock where both apply", () => {
    const result = runStressTest(
      WEIGHTS,
      1000,
      "EUR",
      { name: "mixed", marketShock: -0.1, shockByInstrument: { inst_nvidia: -0.5 } },
      { inst_siemens: { volatility: 0, beta: 1 } },
    );
    // Nvidia uses -0.5 explicitly; Siemens falls back to market×beta.
    // 0.30×-0.5 + 0.20×-0.1×1 = -0.15 - 0.02 = -0.17
    expect(result.navImpactPct).toBeCloseTo(-0.17, 10);
  });
});

import type { PortfolioSnapshot } from "@sonar-ai/core";
import { describe, expect, it } from "vitest";
import { comparePortfolios } from "../compare";
import { proposedWeights } from "../weights";

function bookWith(instrumentId: string, weight: number): PortfolioSnapshot {
  const invested = weight * 1000;
  return {
    id: "pf",
    asOf: "2026-08-29T14:00:00Z",
    baseCurrency: "EUR",
    cash: { amount: 1000 - invested, currency: "EUR" },
    nav: { amount: 1000, currency: "EUR" },
    positions: [
      {
        instrumentId,
        quantity: 1,
        avgPrice: { amount: invested, currency: "EUR" },
        marketValue: { amount: invested, currency: "EUR" },
        weight,
      },
    ],
    label: "synthetic",
  };
}

describe("comparePortfolios with a non-empty starting book", () => {
  const current = bookWith("inst_nvidia", 0.4);
  const proposed = proposedWeights(current, [
    {
      id: "acn_add",
      instrumentId: "inst_siemens",
      side: "buy",
      targetWeight: 0.2,
      amount: { amount: 200, currency: "EUR" },
      evidenceIds: [],
    },
  ]);
  const comparison = comparePortfolios(current, proposed);

  it("adds the new position to the carried-over holding", () => {
    // 0.40 Nvidia (carried) + 0.20 Siemens (new) = 0.60 invested.
    expect(comparison.proposedInvested.amount).toBe(600);
    expect(comparison.proposedCash.amount).toBe(400);
  });

  it("emits a delta for both the held and the new instrument, sorted by id", () => {
    expect(comparison.deltas).toEqual([
      { instrumentId: "inst_nvidia", currentWeight: 0.4, proposedWeight: 0.4 },
      { instrumentId: "inst_siemens", currentWeight: 0, proposedWeight: 0.2 },
    ]);
  });
});

