import type { AgentDef } from "../runner/types";

/**
 * A committee agent, from the agents lane's point of view.
 *
 * The model produces a **draft** (`TDraft`): semantic content only, no IDs. A
 * pure `finalize` turns that draft into the core output type (`TOutput`),
 * assigning deterministic IDs. This keeps structured output robust (the model
 * never invents an ID) and keeps IDs testable and stable across replays.
 *
 * The orchestrator runs `def` through an `AgentRunner`, then calls `finalize`:
 *
 *   const draft = (await runner.run(agent.def, ctx)).output;
 *   const output = agent.finalize(draft, ctx);   // core type, ready for the gate
 *
 * Draft schemas are DERIVED from the core output schemas (via `.omit`), so they
 * can never drift from the contract.
 */
export interface Agent<TContext, TDraft, TOutput> {
  def: AgentDef<TContext, TDraft>;
  finalize(draft: TDraft, context: TContext): TOutput;
}

import {
  ClaimSchema,
  FundamentalReportSchema,
  type Evidence,
  type FundamentalReport,
  type Instrument,
  type Mandate,
} from "@sonar-ai/core";
import { z } from "zod";
import type { Agent } from "./types";

/**
 * Fundamental Analyst — evaluates ONE company's business quality, valuation,
 * financial strength, catalysts, and risks from an isolated evidence pack.
 *
 * Authority: assess asset quality and valuation. It does NOT size positions,
 * discuss portfolio allocation, or read the risk report or other agents' output.
 * The orchestrator calls it once per selected instrument.
 */

/** What the Fundamental Analyst is allowed to see. Populated by the orchestrator. */
export interface FundamentalContext {
  /** The single company under review. */
  instrument: Instrument;
  /** The isolated, pre-fetched evidence pack (fundamentals, filings, news). */
  evidence: Evidence[];
  /** A prior thesis on this instrument, if the fund already holds a view. */
  priorThesis?: string | null;
  /** The mandate, for framing. Not used to size anything. */
  mandate: Mandate;
}

// The model produces content only — no IDs. Drafts are derived from the core
// schemas so they cannot drift from the contract.
const ClaimDraftSchema = ClaimSchema.omit({ id: true });

export const FundamentalReportDraftSchema = FundamentalReportSchema.omit({
  id: true,
  instrumentId: true,
  claims: true,
}).extend({ claims: z.array(ClaimDraftSchema) });
export type FundamentalReportDraft = z.infer<typeof FundamentalReportDraftSchema>;

// ── First-draft prompt (Axel owns the final wording) ─────────────────────────

const INSTRUCTIONS = `You are the Fundamental Analyst on an investment committee.

Evaluate exactly ONE company using ONLY the evidence provided. Assess:
- quality: the durability of the business and its competitive position;
- valuation: whether the price is justified by fundamentals;
- financialStrength: balance sheet, margins, cash generation;
- catalysts: concrete events that could re-rate the asset;
- risks: what could impair the thesis.

Then list claims. Every claim MUST cite one or more evidenceIds drawn ONLY from
the provided pack — never invent an ID or a fact not supported by the evidence.
Mark each claim's stance as "bull", "bear", "neutral", or "context".

Do NOT size positions, recommend a weight, or discuss the rest of the portfolio —
that is the Portfolio Manager's job. Return only the required JSON.`;

function buildInput(ctx: FundamentalContext): string {
  const evidenceBlock =
    ctx.evidence
      .map(
        (e) =>
          `- ${e.id} | ${e.title} | ${e.sourceName} | observed ${e.observedAt} | ${e.label}` +
          (e.snippet ? ` | ${e.snippet}` : ""),
      )
      .join("\n") || "(no evidence provided)";

  return [
    `Company under review: ${ctx.instrument.name} (${ctx.instrument.symbol}) — sector ${ctx.instrument.sector}.`,
    ctx.priorThesis
      ? `Prior thesis on file: ${ctx.priorThesis}`
      : `No prior thesis on file.`,
    `Evidence pack — cite ONLY these evidence IDs:`,
    evidenceBlock,
    `Produce a fundamental assessment as JSON matching the required schema. Every claim.evidenceIds entry MUST be one of the IDs listed above.`,
  ].join("\n\n");
}

/** Assign deterministic IDs, turning the model draft into a core report. */
function finalize(
  draft: FundamentalReportDraft,
  ctx: FundamentalContext,
): FundamentalReport {
  return {
    id: `frp_${ctx.instrument.id}`,
    instrumentId: ctx.instrument.id,
    quality: draft.quality,
    valuation: draft.valuation,
    financialStrength: draft.financialStrength,
    catalysts: draft.catalysts,
    risks: draft.risks,
    claims: draft.claims.map((claim, index) => ({
      id: `clm_${ctx.instrument.id}_${index}`,
      ...claim,
    })),
  };
}

export const fundamentalAnalyst: Agent<
  FundamentalContext,
  FundamentalReportDraft,
  FundamentalReport
> = {
  def: {
    stage: "fundamental_analyst",
    instructions: INSTRUCTIONS,
    outputSchema: FundamentalReportDraftSchema,
    buildInput,
  },
  finalize,
};

import { defineConfig } from "vitest/config";

// Server-lane unit tests only. Runs the pure TypeScript under lib/ in a node
// environment; React component testing is out of scope for now.
export default defineConfig({
  test: {
    environment: "node",
    include: ["lib/**/*.test.ts"],
  },
});

import {
  FundamentalReportSchema,
  type Evidence,
  type Instrument,
  type Mandate,
} from "@sonar-ai/core";
import { describe, expect, it } from "vitest";
import { StubAgentRunner } from "../runner/stub-runner";
import {
  fundamentalAnalyst,
  FundamentalReportDraftSchema,
  type FundamentalContext,
  type FundamentalReportDraft,
} from "./fundamental-analyst";

const INSTRUMENT: Instrument = {
  id: "inst_nvidia",
  symbol: "NVDA",
  name: "Nvidia",
  sector: "Semiconductors",
  assetClass: "equity",
  currency: "EUR",
};

const EVIDENCE: Evidence[] = [
  { id: "ev_nvda_fund", kind: "filing", title: "Nvidia data-center revenue growth", sourceName: "Synthetic filing", observedAt: "2026-08-01T00:00:00Z", label: "synthetic" },
  { id: "ev_nvda_supplier", kind: "cala", title: "GlobalCloud sources GPUs from Nvidia", sourceName: "Cala", observedAt: "2026-08-20T00:00:00Z", label: "synthetic" },
];

const MANDATE: Mandate = {
  id: "mnd_demo1",
  baseCurrency: "EUR",
  initialCash: { amount: 1000, currency: "EUR" },
  limits: { maxGrossExposurePerPosition: 0.3, maxSectorExposure: 0.45, minCashRatio: 0.1, maxTurnoverPerEvent: 0.2 },
};

const CONTEXT: FundamentalContext = {
  instrument: INSTRUMENT,
  evidence: EVIDENCE,
  priorThesis: null,
  mandate: MANDATE,
};

const DRAFT: FundamentalReportDraft = {
  quality: "Dominant AI accelerator franchise with a wide software moat.",
  valuation: "Rich on trailing multiples; justified only if datacenter demand persists.",
  financialStrength: "Strong balance sheet, high gross margins.",
  catalysts: ["GlobalCloud capex cycle"],
  risks: ["Demand air-pocket if AI capex slows"],
  claims: [
    { statement: "Nvidia datacenter revenue is growing on hyperscaler capex.", stance: "bull", evidenceIds: ["ev_nvda_fund"] },
  ],
};

describe("fundamentalAnalyst", () => {
  it("accepts a well-formed draft (no IDs) against its output schema", () => {
    expect(FundamentalReportDraftSchema.safeParse(DRAFT).success).toBe(true);
  });

  it("builds a prompt that names the instrument and exposes every evidence ID", () => {
    const prompt = fundamentalAnalyst.def.buildInput(CONTEXT);
    expect(prompt).toContain("Nvidia");
    for (const e of EVIDENCE) expect(prompt).toContain(e.id);
  });

  it("finalizes a draft into a schema-valid report with deterministic IDs", () => {
    const report = fundamentalAnalyst.finalize(DRAFT, CONTEXT);
    expect(FundamentalReportSchema.safeParse(report).success).toBe(true);
    expect(report.id).toBe("frp_inst_nvidia");
    expect(report.instrumentId).toBe("inst_nvidia");
    expect(report.claims[0]!.id).toBe("clm_inst_nvidia_0");
  });

  it("produces claims whose evidence all resolves to the provided pack", () => {
    const report = fundamentalAnalyst.finalize(DRAFT, CONTEXT);
    const known = new Set(EVIDENCE.map((e) => e.id));
    const referenced = report.claims.flatMap((c) => c.evidenceIds);
    expect(referenced.every((id) => known.has(id))).toBe(true);
  });

  it("runs end-to-end through the StubAgentRunner for one instrument", async () => {
    const runner = new StubAgentRunner({ fundamental_analyst: DRAFT });
    const { output } = await runner.run(fundamentalAnalyst.def, CONTEXT);
    const report = fundamentalAnalyst.finalize(output, CONTEXT);
    expect(FundamentalReportSchema.safeParse(report).success).toBe(true);
  });
});

